CREATE TABLE IF NOT EXISTS experiences (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL DEFAULT 'default', type VARCHAR(20) NOT NULL, title VARCHAR(200) NOT NULL, organization VARCHAR(200), start_date DATE, end_date DATE, raw_description TEXT NOT NULL, structured_achievements JSON, skills_demonstrated JSON, metrics JSON, status VARCHAR(20) NOT NULL DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS personas (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL DEFAULT 'default', name VARCHAR(100) NOT NULL, is_default BOOLEAN NOT NULL DEFAULT 0, identity_statement TEXT, career_narrative TEXT, tone_style VARCHAR(50), capability_weights JSON, target_job_profiles JSON, max_experiences INTEGER NOT NULL DEFAULT 5, preferred_model VARCHAR(100), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS role_experience_weights (id VARCHAR(36) PRIMARY KEY, persona_id VARCHAR(36) NOT NULL REFERENCES personas(id) ON DELETE CASCADE, experience_id VARCHAR(36) NOT NULL REFERENCES experiences(id) ON DELETE CASCADE, relevance_score FLOAT NOT NULL DEFAULT 0, reframed_summary TEXT, highlighted_skills JSON, user_overridden BOOLEAN NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS skill_nodes (id VARCHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, category VARCHAR(50), description TEXT, parent_id VARCHAR(36) REFERENCES skill_nodes(id) ON DELETE SET NULL, aliases JSON, resources JSON, vector_embedding VARCHAR(36), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS job_descs (id VARCHAR(36) PRIMARY KEY, raw_text TEXT NOT NULL, title VARCHAR(200), company VARCHAR(200), years_of_experience VARCHAR(50), salary_range VARCHAR(100), location VARCHAR(200), job_type VARCHAR(50), education_requirement VARCHAR(100), responsibilities JSON, benefits JSON, url VARCHAR(500), parsed_skills JSON, source VARCHAR(50), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS job_matches (id VARCHAR(36) PRIMARY KEY, persona_id VARCHAR(36) NOT NULL REFERENCES personas(id) ON DELETE CASCADE, job_desc_id VARCHAR(36) NOT NULL REFERENCES job_descs(id) ON DELETE CASCADE, match_score INTEGER NOT NULL DEFAULT 0, matched_skills JSON, missing_skills JSON, score_breakdown JSON, notes TEXT, ai_analysis TEXT, tracking_status VARCHAR(20) NOT NULL DEFAULT 'new', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS job_match_experience_reframes (id VARCHAR(36) PRIMARY KEY, job_match_id VARCHAR(36) NOT NULL REFERENCES job_matches(id) ON DELETE CASCADE, experience_id VARCHAR(36) NOT NULL REFERENCES experiences(id) ON DELETE CASCADE, original_summary TEXT NOT NULL, reframed_summary TEXT NOT NULL, reframing_strategy TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_paths (id VARCHAR(36) PRIMARY KEY, persona_id VARCHAR(36) NOT NULL REFERENCES personas(id) ON DELETE CASCADE, target_gap VARCHAR(200), items JSON, source_type VARCHAR(20) DEFAULT 'manual', status VARCHAR(20) NOT NULL DEFAULT 'active', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS uploaded_files (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL DEFAULT 'default', filename VARCHAR(255) NOT NULL, file_type VARCHAR(50) NOT NULL, content_preview TEXT, extracted_count INTEGER NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'processed', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_role_weights_persona ON role_experience_weights(persona_id);
CREATE INDEX IF NOT EXISTS ix_role_weights_experience ON role_experience_weights(experience_id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_role_weights_pair ON role_experience_weights(persona_id, experience_id);
CREATE INDEX IF NOT EXISTS ix_job_matches_persona ON job_matches(persona_id);
CREATE INDEX IF NOT EXISTS ix_job_matches_job ON job_matches(job_desc_id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_job_match_reframes_pair ON job_match_experience_reframes(job_match_id, experience_id);
